        /** Fills {0} {1} in a template: nq_store_checkout_fill($t['arrives'], 'Sep 30'). */
        function nq_store_checkout_fill(string $template, string ...$args): string
        {
            foreach ($args as $i => $arg) {
                $template = str_replace('{'.$i.'}', $arg, $template);
            }

            return $template;
